// Package server is the tifa runtime. Only code generated by the tifa CLI should import it.
package server

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"runtime/debug"
	"slices"
	"strings"
	"time"

	"github.com/liustack/tifa"
	"github.com/liustack/tifa/internal/config"
	"github.com/liustack/tifa/internal/core"
)

// Hooks are the optional functions of the application's hooks.go.
type Hooks struct {
	OnStart    func() error
	OnShutdown func(ctx context.Context) error
	OnRequest  func(c *tifa.Ctx) error
	OnError    func(c *tifa.Ctx, err error) tifa.Error
}

// Renderer draws whole-page HTML. Without one, whole-page results are answered with JSON like interface routes.
type Renderer interface {
	NotFound(c *tifa.Ctx) error
	Error(c *tifa.Ctx, e tifa.Error) error
}

type Server struct {
	Renderer Renderer
	cfg      config.Server
	hooks    Hooks
	mux      *http.ServeMux
	routes   map[string]map[string]func(*tifa.Ctx) error // path, then method
}

func New(cfg config.Config, hooks Hooks) *Server {
	s := &Server{cfg: cfg.Server, hooks: hooks, mux: http.NewServeMux(), routes: map[string]map[string]func(*tifa.Ctx) error{}}
	s.mux.HandleFunc("/", func(w http.ResponseWriter, r *http.Request) { s.serve(w, r, "", nil) })
	return s
}

var methods = []string{"GET", "POST", "PUT", "PATCH", "DELETE"}

// Handle registers the OnXxx function of a route. The path is registered once without a method,
// so OnRequest runs with the matched pattern even when the method has no handler.
// Like http.ServeMux, it panics on invalid or conflicting registrations.
func (s *Server) Handle(method, path string, h func(*tifa.Ctx) error) {
	if !slices.Contains(methods, method) {
		panic(fmt.Sprintf("tifa: unsupported method %q for %s", method, path))
	}
	route, ok := s.routes[path]
	if !ok {
		route = map[string]func(*tifa.Ctx) error{}
		s.routes[path] = route
		s.mux.HandleFunc(path, func(w http.ResponseWriter, r *http.Request) { s.serve(w, r, path, route) })
	}
	if route[method] != nil {
		panic(fmt.Sprintf("tifa: %s %s registered twice", method, path))
	}
	route[method] = h
}

func (s *Server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("X-Content-Type-Options", "nosniff")
	s.mux.ServeHTTP(w, r)
}

// serve runs one request: OnRequest around the route, then the error flow. route is nil when no pattern matched.
func (s *Server) serve(w http.ResponseWriter, r *http.Request, pattern string, route map[string]func(*tifa.Ctx) error) {
	tw := &writer{ResponseWriter: w}
	c := core.New(tw, r, pattern, s.cfg.BodyLimit)
	next := func() error {
		if route == nil {
			return tifa.ErrNotFound
		}
		h := route[r.Method]
		if h == nil && r.Method == "HEAD" {
			h = route["GET"]
		}
		if h == nil {
			methodNotAllowed(tw, route)
			return nil
		}
		return recovered(func() error { return h(c) })
	}
	var err error
	if s.hooks.OnRequest == nil {
		err = next()
	} else {
		core.SetNext(c, next)
		err = recovered(func() error { return s.hooks.OnRequest(c) })
	}
	if err != nil {
		page := route == nil && s.Renderer != nil && (r.Method == "GET" || r.Method == "HEAD") && !c.IsData()
		s.fail(c, tw, err, page)
	}
}

// fail turns an error into a response. Redirects and ErrNotFound are expected results and skip OnError.
func (s *Server) fail(c *tifa.Ctx, w *writer, err error, page bool) {
	r := c.Request()
	var redirect *core.RedirectError
	var e tifa.Error
	switch {
	case errors.As(err, &redirect):
		if w.wrote {
			log.Printf("tifa: %s %s: redirect to %s after the response was written", r.Method, r.URL.Path, redirect.URL)
			return
		}
		http.Redirect(w, r, redirect.URL, redirect.Code)
		return
	case errors.Is(err, tifa.ErrNotFound):
		e = tifa.Error{Status: http.StatusNotFound, Message: http.StatusText(http.StatusNotFound)}
	default:
		e = s.publicError(c, err)
	}
	if w.wrote {
		log.Printf("tifa: %s %s: %v after the response was written", r.Method, r.URL.Path, err)
		return
	}
	var renderErr error
	switch {
	case page && e.Status == http.StatusNotFound:
		renderErr = s.Renderer.NotFound(c)
	case page:
		renderErr = s.Renderer.Error(c, e)
	default:
		writeJSON(w, e.Status, map[string]string{"error": e.Message})
	}
	if renderErr != nil {
		log.Printf("tifa: %s %s: render %d page: %v", r.Method, r.URL.Path, e.Status, renderErr)
		if !w.wrote {
			writeJSON(w, e.Status, map[string]string{"error": e.Message})
		}
	}
}

// publicError asks OnError for the message shown to the client. Without OnError it logs the error,
// keeps a tifa.Error as is and hides everything else behind 500.
func (s *Server) publicError(c *tifa.Ctx, err error) tifa.Error {
	var e tifa.Error
	if s.hooks.OnError != nil {
		e = s.hooks.OnError(c, err)
	} else {
		log.Printf("tifa: %s %s: %v", c.Request().Method, c.Request().URL.Path, err)
		if !errors.As(err, &e) {
			e = tifa.Error{Status: http.StatusInternalServerError}
		}
	}
	if e.Status < 400 || e.Status > 599 {
		e.Status = http.StatusInternalServerError
	}
	if e.Message == "" {
		e.Message = http.StatusText(e.Status)
	}
	return e
}

func methodNotAllowed(w http.ResponseWriter, route map[string]func(*tifa.Ctx) error) {
	var allow []string
	for _, m := range methods {
		if route[m] != nil {
			allow = append(allow, m)
			if m == "GET" {
				allow = append(allow, "HEAD")
			}
		}
	}
	w.Header().Set("Allow", strings.Join(allow, ", "))
	writeJSON(w, http.StatusMethodNotAllowed, map[string]string{"error": http.StatusText(http.StatusMethodNotAllowed)})
}

// recovered turns a panic into an error so it follows the same flow as returned errors.
func recovered(f func() error) (err error) {
	defer func() {
		if p := recover(); p != nil {
			if p == http.ErrAbortHandler {
				panic(p)
			}
			err = fmt.Errorf("tifa: panic: %v\n%s", p, debug.Stack())
		}
	}()
	return f()
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	data, err := json.Marshal(value)
	if err != nil {
		http.Error(w, "JSON encoding failed", 500)
		return
	}
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_, _ = w.Write(data)
}

// writer records whether the response has started, so a late error does not write a second one.
type writer struct {
	http.ResponseWriter
	wrote bool
}

func (w *writer) WriteHeader(code int) {
	w.wrote = true
	w.ResponseWriter.WriteHeader(code)
}

func (w *writer) Write(b []byte) (int, error) {
	w.wrote = true
	return w.ResponseWriter.Write(b)
}

func (w *writer) Unwrap() http.ResponseWriter { return w.ResponseWriter }

// Run calls OnStart, listens on the configured address and serves until ctx is done.
func (s *Server) Run(ctx context.Context) error {
	if s.hooks.OnStart != nil {
		if err := s.hooks.OnStart(); err != nil {
			return fmt.Errorf("tifa: OnStart: %w", err)
		}
	}
	ln, err := net.Listen("tcp", s.cfg.Addr)
	if err != nil {
		return err
	}
	log.Printf("tifa: listening on http://%s", ln.Addr())
	return s.Serve(ctx, ln)
}

// Serve serves on ln until ctx is done, then stops taking requests, waits for in-flight ones and calls OnShutdown.
// Both waits get their own shutdown_timeout.
func (s *Server) Serve(ctx context.Context, ln net.Listener) error {
	srv := &http.Server{Handler: s, ReadHeaderTimeout: 5 * time.Second, ReadTimeout: 10 * time.Second, WriteTimeout: 10 * time.Second, IdleTimeout: 60 * time.Second}
	served := make(chan error, 1)
	go func() { served <- srv.Serve(ln) }()
	select {
	case err := <-served:
		return err
	case <-ctx.Done():
	}
	drain, cancel := context.WithTimeout(context.Background(), s.cfg.ShutdownTimeout)
	err := srv.Shutdown(drain)
	cancel()
	if err != nil {
		err = fmt.Errorf("tifa: waiting for in-flight requests: %w", err)
		_ = srv.Close()
	}
	<-served
	if s.hooks.OnShutdown != nil {
		hookCtx, cancel := context.WithTimeout(context.Background(), s.cfg.ShutdownTimeout)
		defer cancel()
		if hookErr := s.hooks.OnShutdown(hookCtx); hookErr != nil {
			err = errors.Join(err, fmt.Errorf("tifa: OnShutdown: %w", hookErr))
		}
	}
	return err
}
